.stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin: 0 0 16px;
}
.stats div {
  min-width: 8ch;
}
dt,
dd {
  display: inline;
}
dt {
  color: var(--secondary);
  font-size: 14px;
}
dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}
.victory {
  padding: 12px 16px;
  margin-bottom: 12px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.celebrate {
  animation: victory-pulse 600ms ease-out 1;
}
@keyframes victory-pulse {
  50% {
    background: var(--panel);
    opacity: 0.75;
  }
}
@media (prefers-reduced-motion: reduce) {
  .celebrate {
    animation: none;
  }
}
.board-viewport {
  --card-min: 44px;
  --card-max: 88px;
  --card-gap: 6px;
  --board-padding: 6px;
  --board-border: 1px;
  max-height: min(70dvh, 768px);
  overflow: auto;
  overscroll-behavior: contain;
  padding: var(--board-padding);
  border: var(--board-border) solid var(--border);
  border-radius: 12px;
  background: var(--panel);
  width: fit-content;
  max-width: 100%;
}
.board {
  display: grid;
  gap: var(--card-gap);
  grid-template-columns: repeat(var(--grid-size), minmax(var(--card-min), var(--card-max)));
  /* The scroll area's content box already leaves room for page and board scrollbars. */
  width: clamp(
    calc(var(--grid-size) * var(--card-min) + (var(--grid-size) - 1) * var(--card-gap)),
    100%,
    calc(var(--grid-size) * var(--card-max) + (var(--grid-size) - 1) * var(--card-gap))
  );
}
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { boardCode, parseBoardCode } from '../src/game/deck.ts';
import { loadFixedBoard, PHONE } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import { moveKeyboardTo } from './accessibility-tree.ts';
import type { Page } from '@playwright/test';

const SIZE = 16;
// Row 7, column 11 sits past the right edge of a phone board scrolled back to its start.
const REMEMBERED = 6 * SIZE + 10;
// Row 15, column 16 sits past the right and bottom edges of that board.
const FAR = 14 * SIZE + 15;
const EXAMPLE_SIZE = parseBoardCode(EXAMPLE_CODE)?.size ?? 0;

async function scrollBoardToStart(page: Page): Promise<void> {
  await page.locator('.board-viewport').evaluate((viewport) => viewport.scrollTo(0, 0));
  await page.evaluate(() => new Promise((ready) => requestAnimationFrame(ready)));
}

test('Tab and Shift+Tab bring the remembered card in with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const restart = page.getByRole('button', { name: DealControl.restart, exact: true });
  await restart.focus();
  await page.keyboard.press('Tab');
  await moveKeyboardTo(page, REMEMBERED, SIZE);
  const card = page.locator('.card').nth(REMEMBERED);
  for (const enter of ['Shift+Tab', 'Tab']) {
    if (enter === 'Shift+Tab') await page.keyboard.press('Tab');
    else await restart.focus();
    await scrollBoardToStart(page);
    await page.keyboard.press(enter);
    await expect(card).toBeFocused();
    const gaps = await boardGaps(card);
    expect(gaps.right, `I13 ${enter} enters with nearest alignment`).toBeCloseTo(gaps.margin, 0);
  }
});

test('Resume returns focus to the remembered card with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.locator('summary').click();
  const paused = {
    version: SNAPSHOT_VERSION,
    boardCode: boardCode(SIZE, 1),
    matched: [],
    selection: { kind: SelectionKind.one, index: 0 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  };
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(JSON.stringify(paused));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('.card').first().focus();
  await moveKeyboardTo(page, FAR, SIZE);
  const card = page.locator('.card').nth(FAR);
  await expect(card).toBeFocused();
  await scrollBoardToStart(page);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  expect(gaps.right, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
  expect(gaps.bottom, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
});

test('every keyboard move after a pointer click shows the focus outline', async ({ page }) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).click();
  for (const [key, index] of [
    ['ArrowRight', 6],
    ['ArrowDown', 6 + EXAMPLE_SIZE],
    ['ArrowLeft', 5 + EXAMPLE_SIZE],
    ['ArrowUp', 5],
  ] as const) {
    await page.keyboard.press(key);
    await expect(cards.nth(index)).toBeFocused();
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-style', 'solid');
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-width', '3px');
  }
});
import { expect, test } from './browser-test.ts';
import { loadFixedBoard, exportedSnapshot } from './game-fixture.ts';

const COLOR_VECTOR = {
  page: 'rgb(9, 11, 20)',
  panel: 'rgb(20, 24, 39)',
  back: 'rgb(27, 32, 52)',
  face: 'rgb(17, 22, 37)',
  text: 'rgb(244, 246, 255)',
  secondary: 'rgb(184, 189, 210)',
  border: 'rgb(117, 124, 154)',
  focus: 'rgb(255, 255, 255)',
};

test('layout, typography, colors and card geometry match the product values', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 800 });
  await loadFixedBoard(page);
  const style = await page.evaluate(() => {
    const get = (selector: string) => {
      const element = document.querySelector(selector);
      if (!element) throw new Error('Missing style target.');
      return getComputedStyle(element);
    };
    return {
      page: get(':root').backgroundColor,
      text: get(':root').color,
      panel: get('.board-viewport').backgroundColor,
      back: get('.card').backgroundColor,
      border: get('.card').borderColor,
      secondary: get('.help').color,
      bodySize: get(':root').fontSize,
      bodyLine: get(':root').lineHeight,
      titleSize: get('h1').fontSize,
      secondarySize: get('.help').fontSize,
      introSize: get('.intro').fontSize,
      padding: get('main').padding,
      maximum: get('main').maxWidth,
      gap: get('.board').gap,
      cardBorder: get('.card').borderWidth,
      radius: get('.card').borderRadius,
    };
  });
  expect(style).toEqual({
    page: COLOR_VECTOR.page,
    text: COLOR_VECTOR.text,
    panel: COLOR_VECTOR.panel,
    back: COLOR_VECTOR.back,
    border: COLOR_VECTOR.border,
    secondary: COLOR_VECTOR.secondary,
    bodySize: '16px',
    bodyLine: '24px',
    titleSize: '24px',
    secondarySize: '14px',
    introSize: '14px',
    padding: '16px',
    maximum: '1120px',
    gap: '6px',
    cardBorder: '2px',
    radius: '8px',
  });
  await page.locator('.card').first().focus();
  await page.keyboard.press('Enter');
  const focused = await page
    .locator('.card')
    .first()
    .evaluate((element) => {
      const style = getComputedStyle(element);
      return {
        face: style.backgroundColor,
        color: style.outlineColor,
        width: style.outlineWidth,
        offset: style.outlineOffset,
      };
    });
  expect(focused).toEqual({
    face: COLOR_VECTOR.face,
    color: COLOR_VECTOR.focus,
    width: '3px',
    offset: '2px',
  });
});

test('hover changes only card border color and matched marks stay legible', async ({ page }) => {
  await loadFixedBoard(page);
  await page.mouse.move(0, 0);
  const card = page.locator('.card').nth(2);
  const before = await card.evaluate((e) =>
    Object.fromEntries(
      [...getComputedStyle(e)].map((k) => [k, getComputedStyle(e).getPropertyValue(k)]),
    ),
  );
  const progress = await exportedSnapshot(page);
  await card.hover();
  await expect(card).toHaveCSS('border-color', 'rgb(244, 246, 255)');
  const after = await card.evaluate((e) =>
    Object.fromEntries(
      [...getComputedStyle(e)].map((k) => [k, getComputedStyle(e).getPropertyValue(k)]),
    ),
  );
  const changed = Object.keys(before).filter((k) => before[k] !== after[k]);
  expect(changed.length).toBeGreaterThan(0);
  expect(
    changed.filter(
      (k) =>
        !/^border-(?:(?:top|right|bottom|left|block(?:-start|-end)?|inline(?:-start|-end)?)-)?color$/.test(
          k,
        ),
    ),
  ).toEqual([]);
  expect(await exportedSnapshot(page)).toEqual(progress);
  await card.click();
  await page.locator('.card').nth(6).click();
  await expect(page.locator('.stats dd').nth(1)).toHaveText('1/8');
  await page.mouse.move(0, 0);
  await expect(card).toHaveCSS('border-color', 'rgb(139, 234, 125)');
  await expect(card).toHaveCSS('opacity', '1');
  const mark = card.locator('.matched-mark');
  await expect(mark).toBeVisible();
  await expect(mark.locator('path')).toHaveAttribute('d', 'm2 6 3 3 5-6');
});
